t.script:

(function () {
    function initPaymentModal() {
        var root = document.querySelector(".ut-checkout-page");
        if (!root) {
            return;
        }

        var modal = root.querySelector("[data-payment-modal]");
        var openButtons = root.querySelectorAll("[data-payment-open]");
        var closeButtons = root.querySelectorAll("[data-payment-close]");
        var choices = root.querySelectorAll("[data-payment-choice]");
        var paymentGroups = root.querySelectorAll("[data-payment-group]");
        var paymentGroupToggles = root.querySelectorAll("[data-payment-group-toggle]");
        var applyButton = root.querySelector("[data-payment-apply]");
        var paymentGroupPriority = {
            "E-Wallet & QRIS": 10,
            "Transfer Virtual Account": 20
        };
        var hiddenInput = root.querySelector("[data-payment-method-input]");
        var visibleLabel = root.querySelector("[data-payment-label]");
        var visibleLogo = root.querySelector("[data-payment-logo-current]");
        var feeSummary = root.querySelector("[data-payment-fee-summary]");
        var totalSummary = root.querySelector("[data-payment-total-summary]");
        var baseTotal = parseInt(root.dataset.paymentBaseTotal || "0", 10) || 0;
        var selectedValue = hiddenInput ? hiddenInput.value : "bca_va";
        var selectedLabel = visibleLabel ? visibleLabel.textContent.trim() : "BCA Virtual Account";
        var selectedLogoClass = visibleLogo ? visibleLogo.className : "ut-payment-logo";
        var selectedLogoMarkup = visibleLogo ? visibleLogo.innerHTML : "";
        var selectedFee = 0;

        function formatRupiah(value) {
            return "Rp " + (parseInt(value || 0, 10) || 0).toLocaleString("id-ID");
        }

        function bindLogoFallback(scope) {
            var container = scope || root;
            var logoImages = container.querySelectorAll(".ut-payment-logo img");
            logoImages.forEach(function (image) {
                if (image._unitradeLogoFallbackBound) {
                    return;
                }
                image._unitradeLogoFallbackBound = true;
                image.addEventListener("error", function () {
                    var holder = image.closest(".ut-payment-logo");
                    if (holder) {
                        holder.classList.add("is-broken");
                    }
                });
                image.addEventListener("load", function () {
                    var holder = image.closest(".ut-payment-logo");
                    if (holder) {
                        holder.classList.remove("is-broken");
                    }
                });
            });
        }

        function updateVisibleLogo() {
            if (!visibleLogo) {
                return;
            }
            visibleLogo.className = selectedLogoClass;
            visibleLogo.innerHTML = selectedLogoMarkup;
            bindLogoFallback(visibleLogo);
        }

        function openModal(ev) {
            if (ev) {
                ev.preventDefault();
            }
            if (!modal) {
                return;
            }
            modal.classList.add("is-open");
            modal.setAttribute("aria-hidden", "false");
            document.body.classList.add("ut-payment-modal-open");
        }

        function closeModal(ev) {
            if (ev) {
                ev.preventDefault();
            }
            if (!modal) {
                return;
            }
            modal.classList.remove("is-open");
            modal.setAttribute("aria-hidden", "true");
            document.body.classList.remove("ut-payment-modal-open");
        }

        function setPaymentGroupOpen(group, shouldOpen) {
            var toggle = group ? group.querySelector("[data-payment-group-toggle]") : null;
            group.classList.toggle("is-open", shouldOpen);
            if (toggle) {
                toggle.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
            }
        }

        function togglePaymentGroup(group) {
            var shouldOpen = !group.classList.contains("is-open");
            paymentGroups.forEach(function (item) {
                setPaymentGroupOpen(item, item === group ? shouldOpen : false);
            });
        }

        function reorderPaymentGroups() {
            var groups = Array.prototype.slice.call(paymentGroups);
            if (!groups.length || !applyButton || !applyButton.parentNode) {
                return;
            }
            groups.sort(function (left, right) {
                var leftName = left.dataset.paymentGroupName || "";
                var rightName = right.dataset.paymentGroupName || "";
                var leftPriority = paymentGroupPriority[leftName] || 90;
                var rightPriority = paymentGroupPriority[rightName] || 90;
                if (leftPriority !== rightPriority) {
                    return leftPriority - rightPriority;
                }
                return leftName.localeCompare(rightName);
            });
            groups.forEach(function (group, index) {
                applyButton.parentNode.insertBefore(group, applyButton);
                setPaymentGroupOpen(group, index === 0);
            });
        }

        function selectChoice(button) {
            if (button.dataset.paymentEnabled === "0" || button.disabled) {
                return;
            }
            choices.forEach(function (choice) {
                choice.classList.toggle("is-active", choice === button);
            });
            selectedValue = button.dataset.paymentValue || selectedValue;
            selectedLabel = button.dataset.paymentLabelValue || selectedLabel;
            selectedFee = parseInt(button.dataset.paymentFee || "0", 10) || 0;
            var buttonLogo = button.querySelector(".ut-payment-logo");
            if (buttonLogo) {
                selectedLogoClass = buttonLogo.className.replace(/\bis-broken\b/g, "").trim();
                selectedLogoMarkup = buttonLogo.innerHTML;
            }
        }

        reorderPaymentGroups();
        bindLogoFallback(root);
        openButtons.forEach(function (button) {
            button.addEventListener("click", openModal);
        });
        closeButtons.forEach(function (button) {
            button.addEventListener("click", closeModal);
        });
        paymentGroupToggles.forEach(function (button) {
            button.addEventListener("click", function (ev) {
                ev.preventDefault();
                var group = button.closest("[data-payment-group]");
                if (group) {
                    togglePaymentGroup(group);
                }
            });
        });
        choices.forEach(function (button) {
            if (button.classList.contains("is-active")) {
                selectedFee = parseInt(button.dataset.paymentFee || "0", 10) || 0;
            }
            button.addEventListener("click", function (ev) {
                ev.preventDefault();
                selectChoice(button);
            });
        });
        if (applyButton) {
            applyButton.addEventListener("click", function (ev) {
                ev.preventDefault();
                if (hiddenInput) {
                    hiddenInput.value = selectedValue;
                }
                if (visibleLabel) {
                    visibleLabel.textContent = selectedLabel;
                }
                if (feeSummary) {
                    feeSummary.textContent = formatRupiah(selectedFee);
                }
                if (totalSummary) {
                    totalSummary.textContent = formatRupiah(baseTotal + selectedFee);
                }
                updateVisibleLogo();
                closeModal();
            });
        }
        document.addEventListener("unitrade:voucher-updated", function (ev) {
            var detail = ev.detail || {};
            baseTotal = parseInt(detail.baseTotal || root.dataset.paymentBaseTotal || "0", 10) || 0;
            if (totalSummary) {
                totalSummary.textContent = formatRupiah(baseTotal + selectedFee);
            }
        });
        document.addEventListener("keydown", function (ev) {
            if (ev.key === "Escape" && modal && modal.classList.contains("is-open")) {
                closeModal(ev);
            }
        });
    }

    function initVoucher() {
        var root = document.querySelector(".ut-checkout-page");
        if (!root) {
            return;
        }
        var input = root.querySelector("[data-voucher-input]");
        var applyButton = root.querySelector("[data-voucher-apply]");
        var removeButton = root.querySelector("[data-voucher-remove]");
        var message = root.querySelector("[data-voucher-message]");
        var row = root.querySelector("[data-voucher-summary-row]");
        var codeLabel = root.querySelector("[data-voucher-code-label]");
        var discountSummary = root.querySelector("[data-voucher-discount-summary]");
        var totalSummary = root.querySelector("[data-payment-total-summary]");
        var paymentFeeSummary = root.querySelector("[data-payment-fee-summary]");
        var paymentInput = root.querySelector("[data-payment-method-input]");

        function setMessage(text, type) {
            if (!message) {
                return;
            }
            message.textContent = text || "";
            message.classList.toggle("is-success", type === "success");
            message.classList.toggle("is-error", type === "error");
        }

        function rpc(url, params) {
            return fetch(url, {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: params || {}
                })
            }).then(function (response) {
                return response.json();
            }).then(function (payload) {
                return payload.result || payload;
            });
        }

        function setBusy(isBusy) {
            [applyButton, removeButton, input].forEach(function (node) {
                if (node) {
                    node.disabled = !!isBusy;
                }
            });
        }

        function updateSummary(data) {
            var hasVoucher = !!(data && data.voucher_discount);
            if (row) {
                row.classList.toggle("tw-hidden", !hasVoucher);
            }
            if (removeButton) {
                removeButton.classList.toggle("tw-hidden", !hasVoucher);
            }
            if (codeLabel) {
                codeLabel.textContent = data.voucher_name || data.voucher_code || "";
            }
            if (discountSummary) {
                discountSummary.textContent = hasVoucher ? "-" + data.voucher_discount_label : "";
            }
            if (totalSummary && data.total_label) {
                totalSummary.textContent = data.total_label;
            }
            if (paymentFeeSummary && data.payment_fee_label) {
                paymentFeeSummary.textContent = data.payment_fee_label;
            }
            if (input) {
                // Kosongkan input setelah voucher diterapkan; input hanya untuk
                // memasukkan kode, label voucher ditampilkan di ringkasan.
                input.value = "";
            }
            var baseTotal = Math.max((parseInt(data.total || 0, 10) || 0) - (parseInt(data.payment_fee || 0, 10) || 0), 0);
            root.dataset.paymentBaseTotal = String(baseTotal);
            document.dispatchEvent(new CustomEvent("unitrade:voucher-updated", {
                detail: {baseTotal: baseTotal}
            }));
        }

        if (applyButton) {
            applyButton.addEventListener("click", function (ev) {
                ev.preventDefault();
                var code = input ? input.value.trim() : "";
                if (!code) {
                    setMessage("Masukkan kode voucher.", "error");
                    return;
                }
                setBusy(true);
                rpc("/unitrade/checkout/voucher/apply", {
                    code: code,
                    payment_method: paymentInput ? paymentInput.value : "bca_va"
                }).then(function (data) {
                    if (data.success) {
                        updateSummary(data);
                        setMessage(data.message || "Voucher berhasil diterapkan.", "success");
                    } else {
                        setMessage(data.message || "Voucher tidak valid.", "error");
                    }
                }).catch(function () {
                    setMessage("Voucher belum bisa diterapkan. Coba lagi.", "error");
                }).finally(function () {
                    setBusy(false);
                });
            });
        }

        if (removeButton) {
            removeButton.addEventListener("click", function (ev) {
                ev.preventDefault();
                setBusy(true);
                rpc("/unitrade/checkout/voucher/remove", {
                    payment_method: paymentInput ? paymentInput.value : "bca_va"
                }).then(function (data) {
                    if (data.success) {
                        if (input) {
                            input.value = "";
                        }
                        updateSummary(data);
                        setMessage(data.message || "Voucher dihapus.", "success");
                    } else {
                        setMessage(data.message || "Voucher belum bisa dihapus.", "error");
                    }
                }).catch(function () {
                    setMessage("Voucher belum bisa dihapus. Coba lagi.", "error");
                }).finally(function () {
                    setBusy(false);
                });
            });
        }
    }

    function initShipping() {
        var root = document.querySelector(".ut-checkout-page");
        if (!root) {
            return;
        }
        var radios = root.querySelectorAll("[data-shipping-radio]");
        if (!radios.length) {
            return;
        }
        var options = root.querySelectorAll("[data-shipping-option]");
        var costSummary = root.querySelector("[data-shipping-cost-summary]");
        var methodLabel = root.querySelector("[data-shipping-method-label]");
        var totalSummary = root.querySelector("[data-payment-total-summary]");
        var paymentFeeSummary = root.querySelector("[data-payment-fee-summary]");
        var warningBox = root.querySelector("[data-shipping-gps-warning]");
        var warningText = root.querySelector("[data-shipping-gps-warning-text]");
        var paymentInput = root.querySelector("[data-payment-method-input]");

        function rpc(url, params) {
            return fetch(url, {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: params || {}
                })
            }).then(function (response) {
                return response.json();
            }).then(function (payload) {
                return payload.result || payload;
            });
        }

        function setActive(key) {
            options.forEach(function (opt) {
                opt.classList.toggle("is-active", opt.dataset.shippingOption === key);
            });
        }

        function showWarning(text) {
            if (!warningBox || !warningText) {
                return;
            }
            if (text) {
                warningText.textContent = text;
                warningBox.style.display = "flex";
            } else {
                warningText.textContent = "";
                warningBox.style.display = "none";
            }
        }

        function applyResult(data) {
            if (costSummary && data.shipping_cost_label) {
                costSummary.textContent = data.shipping_cost_label;
            }
            if (methodLabel) {
                methodLabel.textContent = data.shipping_method === "gosend" ? "GoSend Instant" : "Ambil Sendiri";
            }
            if (paymentFeeSummary && data.payment_fee_label) {
                paymentFeeSummary.textContent = data.payment_fee_label;
            }
            if (totalSummary && data.total_label) {
                totalSummary.textContent = data.total_label;
            }
            showWarning(data.gps_warning);
            var baseTotal = Math.max((parseInt(data.total || 0, 10) || 0) - (parseInt(data.payment_fee || 0, 10) || 0), 0);
            root.dataset.paymentBaseTotal = String(baseTotal);
            document.dispatchEvent(new CustomEvent("unitrade:voucher-updated", {
                detail: {baseTotal: baseTotal}
            }));
        }

        radios.forEach(function (radio) {
            radio.addEventListener("change", function () {
                if (!radio.checked) {
                    return;
                }
                var key = radio.value;
                setActive(key);
                radios.forEach(function (r) { r.disabled = true; });
                rpc("/unitrade/checkout/shipping/select", {
                    shipping_method: key,
                    payment_method: paymentInput ? paymentInput.value : "bca_va"
                }).then(function (data) {
                    if (data.success) {
                        applyResult(data);
                    } else {
                        showWarning(data.message || "Metode pengiriman tidak valid.");
                    }
                }).catch(function () {
                    showWarning("Metode pengiriman belum bisa diperbarui. Coba lagi.");
                }).finally(function () {
                    radios.forEach(function (r) { r.disabled = false; });
                });
            });
        });
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function () {
            initPaymentModal();
            initVoucher();
            initShipping();
        });
    } else {
        initPaymentModal();
        initVoucher();
        initShipping();
    }
}());
